  1	<!DOCTYPE html>
  2	<html lang="en">
  3	<head>
  4	<meta charset="utf-8">
  5	<meta name="viewport" content="width=device-width, initial-scale=1">
  6	<title>Calculator</title>
  7	<style>
  8	  * { box-sizing: border-box; }
  9	  body {
 10	    margin: 0;
 11	    min-height: 100vh;
 12	    display: flex;
 13	    align-items: center;
 14	    justify-content: center;
 15	    background: #eceef1;
 16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
 17	  }
 18	  .calc {
 19	    position: relative;
 20	    width: 320px;
 21	    max-width: calc(100vw - 32px);
 22	    padding: 16px;
 23	    background: #1f2328;
 24	    border-radius: 20px;
 25	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
 26	  }
 27	  .display {
 28	    height: 88px;
 29	    padding: 0 12px;
 30	    margin-bottom: 16px;
 31	    display: flex;
 32	    align-items: flex-end;
 33	    justify-content: flex-end;
 34	    color: #fff;
 35	    font-size: 48px;
 36	    font-weight: 300;
 37	    white-space: nowrap;
 38	    overflow: hidden;
 39	    font-variant-numeric: tabular-nums;
 40	  }
 41	  .groups {
 42	    position: absolute;
 43	    top: 22px;
 44	    left: 28px;
 45	    color: #9aa0a6;
 46	    font-size: 18px;
 47	    letter-spacing: 2px;
 48	  }
 49	  .display.small { font-size: 32px; }
 50	  .display.tiny { font-size: 22px; }
 51	  .keys {
 52	    display: grid;
 53	    grid-template-columns: repeat(4, 1fr);
 54	    gap: 10px;
 55	  }
 56	  button {
 57	    height: 64px;
 58	    border: 0;
 59	    border-radius: 14px;
 60	    font: inherit;
 61	    font-size: 24px;
 62	    color: #fff;
 63	    background: #3a4048;
 64	    cursor: pointer;
 65	    user-select: none;
 66	  }
 67	  button:hover { filter: brightness(1.12); }
 68	  button:active { filter: brightness(0.9); }
 69	  button:focus-visible { outline: 2px solid #8ab4f8; outline-offset: 2px; }
 70	  .op { background: #f59e0b; }
 71	  .op.active { background: #fff; color: #f59e0b; }
 72	  .fn { background: #9aa0a6; color: #111; }
 73	  .wide { grid-column: span 2; }
 74	
 75	  .app {
 76	    display: flex;
 77	    flex-wrap: wrap;
 78	    align-items: flex-start;
 79	    justify-content: center;
 80	    gap: 16px;
 81	    padding: 16px;
 82	  }
 83	  .tape-panel {
 84	    display: flex;
 85	    flex-direction: column;
 86	    width: 280px;
 87	    max-width: calc(100vw - 32px);
 88	    height: 570px;
 89	    background: #fff;
 90	    border-radius: 20px;
 91	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.12);
 92	    overflow: hidden;
 93	  }
 94	  .tape-head {
 95	    display: flex;
 96	    align-items: center;
 97	    justify-content: space-between;
 98	    padding: 12px 12px 12px 20px;
 99	    border-bottom: 1px solid #e3e5e8;
100	    color: #5f6368;
101	    font-size: 14px;
102	    font-weight: 600;
103	  }
104	  .tape-clear {
105	    height: 32px;
106	    padding: 0 12px;
107	    border-radius: 8px;
108	    font-size: 14px;
109	    color: #1f2328;
110	    background: #eceef1;
111	  }
112	  .tape {
113	    flex: 1;
114	    min-height: 0;
115	    overflow-y: auto;
116	  }
117	  .tape-row {
118	    padding: 10px 20px;
119	    border-bottom: 1px solid #f0f1f3;
120	    text-align: right;
121	    font-variant-numeric: tabular-nums;
122	    overflow-wrap: anywhere;
123	  }
124	  .tape-expr { display: block; color: #5f6368; font-size: 14px; }
125	  .tape-result { display: block; color: #1f2328; font-size: 22px; }
126	  .tape-empty { margin: 0; padding: 20px; color: #9aa0a6; font-size: 14px; text-align: center; }
127	  @media (max-width: 660px) {
128	    .tape-panel { height: auto; width: 320px; }
129	    .tape { max-height: 280px; }
130	  }
131	</style>
132	</head>
133	<body>
134	<div class="app">
135	<div class="calc">
136	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" role="status" aria-live="polite">0</div>
137	  <div class="groups" data-testid="calc-groups" aria-hidden="true"></div>
138	  <div class="keys">
139	    <button class="fn wide" data-testid="key-lparen" data-action="lparen" aria-label="open group">(</button>
140	    <button class="fn wide" data-testid="key-rparen" data-action="rparen" aria-label="close group">)</button>
141	
142	    <button class="fn wide" data-testid="key-clear" data-action="clear">AC</button>
143	    <button class="fn" data-testid="key-sign" data-action="sign" aria-label="change sign">±</button>
144	    <button class="op" data-testid="key-div" data-op="/" aria-label="divide">÷</button>
145	
146	    <button data-testid="key-7" data-digit="7">7</button>
147	    <button data-testid="key-8" data-digit="8">8</button>
148	    <button data-testid="key-9" data-digit="9">9</button>
149	    <button class="op" data-testid="key-mul" data-op="*" aria-label="multiply">×</button>
150	
151	    <button data-testid="key-4" data-digit="4">4</button>
152	    <button data-testid="key-5" data-digit="5">5</button>
153	    <button data-testid="key-6" data-digit="6">6</button>
154	    <button class="op" data-testid="key-sub" data-op="-" aria-label="subtract">−</button>
155	
156	    <button data-testid="key-1" data-digit="1">1</button>
157	    <button data-testid="key-2" data-digit="2">2</button>
158	    <button data-testid="key-3" data-digit="3">3</button>
159	    <button class="op" data-testid="key-add" data-op="+" aria-label="add">+</button>
160	
161	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
162	    <button data-testid="key-dot" data-action="dot" aria-label="decimal point">.</button>
163	    <button class="op" data-testid="key-equals" data-action="equals" aria-label="equals">=</button>
164	  </div>
165	</div>
166	<section class="tape-panel" aria-label="Past calculations">
167	  <div class="tape-head">
168	    <span>Tape</span>
169	    <button class="tape-clear" data-testid="tape-clear">Clear</button>
170	  </div>
171	  <div class="tape" data-testid="calc-tape"></div>
172	  <p class="tape-empty">No calculations yet</p>
173	</section>
174	</div>
175	<script>
176	(function () {
177	  var display = document.querySelector('[data-testid="calc-display"]');
178	  var groupsEl = document.querySelector('[data-testid="calc-groups"]');
179	  var opButtons = document.querySelectorAll('[data-op]');
180	  var tape = document.querySelector('[data-testid="calc-tape"]');
181	  var tapeEmpty = document.querySelector('.tape-empty');
182	  var opSymbols = { '+': '+', '-': '−', '*': '×', '/': '÷' };
183	
184	  var state;
185	
186	  function reset() {
187	    state = {
188	      entry: '0',        // text of the number being typed
189	      value: 0,          // exact current value when not typing; never rounded
190	      stored: null,      // left operand
191	      op: null,          // pending operator
192	      typing: false,     // true while the user is building an entry
193	      edited: false,     // true when ± or ) turned the display into the entry
194	      lastOp: null,      // for repeated equals
195	      lastOperand: null,
196	      groups: [],        // one saved {stored, op, tokens} per open parenthesis
197	      tokens: [],        // expression text so far at this group level; ends with op when op is set
198	      entryExpr: null,   // expression text for an entry made by ), e.g. "(3 × 4)"
199	      error: false
200	    };
201	  }
202	
203	  function compute(a, op, b) {
204	    switch (op) {
205	      case '+': return a + b;
206	      case '-': return a - b;
207	      case '*': return a * b;
208	      case '/': return b === 0 ? NaN : a / b;
209	    }
210	    return b;
211	  }
212	
213	  function currentValue() {
214	    return state.typing ? parseFloat(state.entry) : state.value;
215	  }
216	
217	  // True when the display holds an entry: typed, or changed by ± or ).
218	  function hasEntry() {
219	    return state.typing || state.edited;
220	  }
221	
222	  // Expression text for the current entry, for the tape.
223	  function entryText() {
224	    return state.entryExpr !== null ? state.entryExpr : format(currentValue());
225	  }
226	
227	  function addTapeRow(expr, n) {
228	    var row = document.createElement('div');
229	    row.className = 'tape-row';
230	    row.setAttribute('data-testid', 'tape-row');
231	    var e = document.createElement('span');
232	    e.className = 'tape-expr';
233	    e.setAttribute('data-testid', 'tape-expr');
234	    e.textContent = expr;
235	    var r = document.createElement('span');
236	    r.className = 'tape-result';
237	    r.setAttribute('data-testid', 'tape-result');
238	    r.setAttribute('data-value', String(n));
239	    r.textContent = format(n);
240	    row.appendChild(e);
241	    row.appendChild(r);
242	    tape.insertBefore(row, tape.firstChild);
243	    tape.scrollTop = 0;
244	    tapeEmpty.hidden = true;
245	  }
246	
247	  function clearTape() {
248	    tape.textContent = '';
249	    tapeEmpty.hidden = false;
250	  }
251	
252	  // Presentation only: at most 10 significant digits, no trailing zeros,
253	  // exponential notation when |n| >= 1e10 or |n| < 1e-9. Never feed the
254	  // result back into a calculation.
255	  function format(n) {
256	    var m = Math.abs(n).toExponential(9).match(/^(\d)\.(\d+)e([+-]\d+)$/);
257	    var digits = m[1] + m[2];
258	    var exp = parseInt(m[3], 10);
259	    var sign = n < 0 ? '-' : '';
260	    var intPart, frac;
261	    if (Number(digits) === 0) return '0';
262	    if (exp >= 10 || exp < -9) {
263	      frac = m[2].replace(/0+$/, '');
264	      return sign + m[1] + (frac ? '.' + frac : '') + 'e' + (exp < 0 ? '-' : '+') + Math.abs(exp);
265	    }
266	    if (exp >= 0) {
267	      intPart = digits.slice(0, exp + 1);
268	      frac = digits.slice(exp + 1);
269	    } else {
270	      intPart = '0';
271	      frac = new Array(-exp).join('0') + digits;
272	    }
273	    frac = frac.replace(/0+$/, '');
274	    return sign + intPart + (frac ? '.' + frac : '');
275	  }
276	
277	  function render() {
278	    var text, value;
279	    if (state.error) {
280	      text = 'Error';
281	      value = 'NaN';
282	    } else {
283	      value = currentValue();
284	      text = state.typing ? state.entry : format(value);
285	      value = String(value);
286	    }
287	    display.textContent = text;
288	    display.setAttribute('data-value', value);
289	    display.setAttribute('data-error', state.error ? 'true' : 'false');
290	    display.setAttribute('data-open-groups', String(state.groups.length));
291	    groupsEl.textContent = new Array(state.groups.length + 1).join('(');
292	    display.classList.toggle('small', text.length > 9 && text.length <= 13);
293	    display.classList.toggle('tiny', text.length > 13);
294	    for (var i = 0; i < opButtons.length; i++) {
295	      var b = opButtons[i];
296	      b.classList.toggle('active', !hasEntry() && state.op === b.getAttribute('data-op'));
297	    }
298	  }
299	
300	  function setResult(n) {
301	    if (!isFinite(n)) {
302	      reset();
303	      state.error = true;
304	    } else {
305	      state.value = n;
306	    }
307	  }
308	
309	  function inputDigit(d) {
310	    if (!state.typing) {
311	      state.entry = d;
312	      state.typing = true;
313	      state.edited = false;
314	      state.entryExpr = null;
315	      if (state.op === null) state.lastOp = null;
316	    } else if (state.entry === '0' || state.entry === '-0') {
317	      state.entry = state.entry.slice(0, -1) + d;
318	    } else if (state.entry.replace(/[-.]/g, '').length < 16) {
319	      state.entry += d;
320	    }
321	  }
322	
323	  function inputDot() {
324	    if (!state.typing) {
325	      state.entry = '0.';
326	      state.typing = true;
327	      state.edited = false;
328	      state.entryExpr = null;
329	      if (state.op === null) state.lastOp = null;
330	    } else if (state.entry.indexOf('.') === -1) {
331	      state.entry += '.';
332	    }
333	  }
334	
335	  // ± acts on the current entry at once. While typing, ± keeps the
336	  // entry editable. Otherwise the displayed value becomes the entry, so
337	  // after an operator it is the right operand: 5 + ± = is 0.
338	  function toggleSign() {
339	    if (state.typing) {
340	      state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
341	    } else if (state.value === 0) {
342	      // Start a negative entry: ± 5 is -5.
343	      state.entry = '-0';
344	      state.typing = true;
345	      state.edited = false;
346	      state.entryExpr = null;
347	      if (state.op === null) state.lastOp = null;
348	    } else {
349	      state.value = -state.value;
350	      state.edited = true;
351	      if (state.entryExpr !== null) {
352	        state.entryExpr = state.entryExpr.charAt(0) === '-' ? state.entryExpr.slice(1) : '-' + state.entryExpr;
353	      }
354	    }
355	  }
356	
357	  // Immediate execution, strictly left to right, no operator precedence:
358	  // 2 + 3 × 4 = is 20. An operator key first finishes the operation already
359	  // waiting, so the display always shows a real running result.
360	  function inputOp(op) {
361	    var v = currentValue();
362	    var text = entryText();
363	    if (state.op !== null && hasEntry()) {
364	      setResult(compute(state.stored, state.op, v));
365	      if (state.error) return;
366	      state.tokens.push(text, opSymbols[op]);
367	    } else if (state.op !== null) {
368	      // Replacing the waiting operator.
369	      state.value = v;
370	      state.tokens[state.tokens.length - 1] = opSymbols[op];
371	    } else {
372	      state.value = v;
373	      state.tokens = [text, opSymbols[op]];
374	    }
375	    state.stored = state.value;
376	    state.op = op;
377	    state.typing = false;
378	    state.edited = false;
379	    state.entryExpr = null;
380	    state.lastOp = null;
381	  }
382	
383	  // Parentheses keep immediate execution. ( saves the waiting operation and
384	  // starts a fresh calculation, like a new number would. ) finishes that
385	  // calculation, restores the saved operation, and leaves the group result
386	  // as the entry: 2 + ( 3 × 4 ) = is 14. Groups nest.
387	  function openGroup() {
388	    state.groups.push({ stored: state.stored, op: state.op, tokens: state.tokens });
389	    state.stored = null;
390	    state.op = null;
391	    state.tokens = [];
392	    state.value = 0;
393	    state.typing = false;
394	    state.edited = false;
395	    state.entryExpr = null;
396	    state.lastOp = null;
397	  }
398	
399	  function closeGroup() {
400	    if (state.groups.length === 0) return;
401	    var inner;
402	    if (state.op !== null && hasEntry()) {
403	      inner = state.tokens.concat(entryText());
404	      setResult(compute(state.stored, state.op, currentValue()));
405	      if (state.error) return;
406	    } else {
407	      // A trailing operator with no operand is dropped: ( 2 + ) is 2.
408	      inner = state.op !== null ? state.tokens.slice(0, -1) : [entryText()];
409	      state.value = currentValue();
410	    }
411	    var saved = state.groups.pop();
412	    state.stored = saved.stored;
413	    state.op = saved.op;
414	    state.tokens = saved.tokens;
415	    state.entryExpr = '(' + inner.join(' ') + ')';
416	    state.typing = false;
417	    state.edited = true;
418	    state.lastOp = null;
419	  }
420	
421	  function equals() {
422	    // = closes any groups still open.
423	    while (state.groups.length > 0 && !state.error) closeGroup();
424	    if (state.error) return;
425	    var expr = null;
426	    if (state.op !== null) {
427	      var b = hasEntry() ? currentValue() : state.stored;
428	      expr = state.tokens.concat(hasEntry() ? entryText() : format(b));
429	      state.lastOp = state.op;
430	      state.lastOperand = b;
431	      setResult(compute(state.stored, state.op, b));
432	    } else if (state.lastOp !== null) {
433	      // Repeated equals: apply the last operation again.
434	      expr = [entryText(), opSymbols[state.lastOp], format(state.lastOperand)];
435	      setResult(compute(currentValue(), state.lastOp, state.lastOperand));
436	    } else {
437	      // A lone number is not a calculation; a group result is.
438	      if (hasEntry() && state.entryExpr !== null) expr = [state.entryExpr];
439	      state.value = currentValue();
440	    }
441	    if (state.error) return;
442	    if (expr !== null) addTapeRow(expr.join(' '), state.value);
443	    state.op = null;
444	    state.stored = null;
445	    state.tokens = [];
446	    state.typing = false;
447	    state.edited = false;
448	    state.entryExpr = null;
449	  }
450	
451	  function handle(el) {
452	    var digit = el.getAttribute('data-digit');
453	    var op = el.getAttribute('data-op');
454	    var action = el.getAttribute('data-action');
455	    // In the error state only clear does anything.
456	    if (state.error && action !== 'clear') return;
457	    if (digit !== null) inputDigit(digit);
458	    else if (op !== null) inputOp(op);
459	    else if (action === 'dot') inputDot();
460	    else if (action === 'sign') toggleSign();
461	    else if (action === 'lparen') openGroup();
462	    else if (action === 'rparen') closeGroup();
463	    else if (action === 'equals') equals();
464	    else if (action === 'clear') reset();
465	    render();
466	  }
467	
468	  document.querySelector('.keys').addEventListener('click', function (e) {
469	    var el = e.target.closest('button');
470	    if (el) handle(el);
471	  });
472	
473	  document.querySelector('[data-testid="tape-clear"]').addEventListener('click', clearTape);
474	
475	  var keyMap = {
476	    '+': 'key-add', '-': 'key-sub', '*': 'key-mul', 'x': 'key-mul', '/': 'key-div',
477	    '.': 'key-dot', '(': 'key-lparen', ')': 'key-rparen', ',': 'key-dot', '=': 'key-equals', 'Enter': 'key-equals',
478	    'Escape': 'key-clear', 'c': 'key-clear', 'C': 'key-clear', 'Delete': 'key-clear'
479	  };
480	  document.addEventListener('keydown', function (e) {
481	    if (e.ctrlKey || e.metaKey || e.altKey) return;
482	    var id = /^[0-9]$/.test(e.key) ? 'key-' + e.key : keyMap[e.key];
483	    if (!id) return;
484	    e.preventDefault();
485	    handle(document.querySelector('[data-testid="' + id + '"]'));
486	  });
487	
488	  reset();
489	  render();
490	})();
491	</script>
492	</body>
493	</html>

